("¿Cómo se conjuga «estar»?","estic, estàs, està, estem, esteu, estan.",["verbos","ser estar"],["estar presente"]),
("¿Cómo se conjuga «tindre»?","tinc, tens, té, tenim, teniu, tenen. «Tindre» y «tenir» son normativos.",["verbos"],["tener","tindre tenir"]),
("¿Cómo se conjuga «anar»?","vaig, vas, va, anem, aneu, van.",["verbos"],["ir","anar presente"]),
("¿Cómo se conjuga «fer»?","faig, fas, fa, fem, feu, fan.",["verbos"],["hacer","fer presente"]),
("¿Cómo se conjuga «poder»?","puc, pots, pot, podem, podeu, poden.",["verbos"],["poder presente"]),
("¿Cómo se conjuga «voler»?","vull, vols, vol, volem, voleu, volen.",["verbos"],["querer","voler presente"]),
("¿Cómo se conjuga «saber»?","sé, saps, sap, sabem, sabeu, saben.",["verbos"],["saber presente"]),
("¿Cómo se conjuga «vindre»?","vinc, véns, ve, venim, veniu, vénen. «Vindre» y «venir» son normativos.",["verbos"],["venir"]),
("¿Cómo se conjuga «dir»?","dic, dius, diu, diem, dieu, diuen.",["verbos"],["decir"]),
("¿Cómo se conjuga «vore/veure»?","veig, veus, veu, veiem, veieu, veuen. «Vore» y «veure» son normativos.",["verbos","formas valencianas"],["ver","vore veure"]),
# --- perquè / per què, etc.
("¿«Perquè» o «per què»?","«Per què» (separado y con acento) pregunta: per què no véns? «Perquè» (junto) responde o explica: perquè plou.",["perque","ortografia"],["porque por que","perque per que"]),
("¿«Sinó» o «si no»?","«Sinó» = sino (no és roig sinó blau). «Si no» = si no (si no plou, eixirem).",["ortografia","conectores"],["sino si no"]),
("¿«Què» o «que»?","«Què» con acento es interrogativo o exclamativo (què fas?). «Que» sin acento es conjunción o relativo (crec que…).",["ortografia"],["que què"]),
("¿«Com» o «com que»?","«Com» = cómo / como. «Com que» = como (causal, al principio de la frase): com que plovia, no vaig eixir.",["conectores"],["como"]),
("¿«També» o «tampoc»?","«També» = también (afirmativo). «Tampoc» = tampoco (negativo): a mi tampoc m'agrada.",["adverbios"],["tambien tampoco"]),
("¿Cómo se dice «todavía»?","«Encara»: encara no he dinat.",["adverbios"],["todavia aun encara"]),
("¿Cómo se dice «nunca»? ¿Lleva «no»?","«Mai». En frases con el verbo detrás se recomienda «mai no»: mai no he estat a Londres. Sola: «Mai!».",["adverbios","negacion"],["nunca mai"]),
("¿Cómo se dice «nada»: «res» o «gens»?","«Res» = nada (no vull res). «Gens» = nada de, con cantidades (no tinc gens de son).",["cuantificadores","negacion"],["nada res gens"]),
("¿Cómo se dice «demasiado»?","«Massa»: massa car, massa gent.",["cuantificadores"],["demasiado massa"]),
("¿Cómo se dice «bastante»?","«Prou» (suficiente) o «bastant». «Ja n'hi ha prou!» = ¡ya basta!",["cuantificadores"],["bastante prou"]),
# --- artículos
("¿Cuáles son los artículos?","Determinados: el, la, els, les (l' ante vocal). Indeterminados: un, una, uns, unes.",["articulos"],["articulos","el la els les"]),
("¿Se pone artículo delante de nombres de persona?","En valenciano coloquial es habitual: «el Pau», «la Marta». En registro formal se puede omitir.",["articulos","nombres"],["articulo nombre propio","la Marta"]),
("¿Por qué se dice «al març»?","Con meses se usa «a» + artículo opcional: al març / a març. «Al març» = en marzo.",["articulos","fechas"],["en marzo","al"]),
("¿Cómo son las contracciones?","a + el = al, de + el = del, per + el = pel; con plural: als, dels, pels.",["articulos","preposiciones"],["al del pel","contracciones"]),
# --- posesivos
("¿«Meua» o «meva»?","En valenciano: meu, meua, meus, meues (y teu/teua, seu/seua). «Meva» es la forma del catalán central; la AVL admite ambas, pero la valenciana es «meua».",["posesivos","formas valencianas"],["meua meva","mi mia"]),
("¿Los posesivos llevan artículo?","Sí: el meu pare, la meua mare, els meus fills. Sin artículo solo en expresiones fijas o tras «ser»: és meu.",["posesivos","articulos"],["mi padre","el meu"]),
("¿Cómo se dice «su» (de él/ella)?","«El seu / la seua / els seus / les seues». Para «de ellos» también se usa «el seu» o «el d'ells».",["posesivos"],["su suyo"]),
("¿Cómo se dice «nuestro» y «vuestro»?","El nostre, la nostra, els nostres, les nostres; el vostre, la vostra…",["posesivos"],["nuestro vuestro"]),
