# --- verbos: grupos y tiempos
("¿Cuáles son los grupos verbales?","Tres conjugaciones: -ar (parlar), -er/-re (témer, perdre, vore) y -ir (dormir, servir). Muchos en -ir son incoativos: servir → servisc, servixes.",["verbos"],["conjugaciones","grupos verbales"]),
("¿Qué son los verbos incoativos?","Verbos en -ir que añaden -isc/-ix: servir → servisc, servixes, servix, servim, serviu, servixen. Otros: patir (patisc), oferir (oferisc). No lo son dormir ni obrir.",["verbos"],["incoativos","servisc"]),
("¿Por qué «parle» acaba en -e?","Es la 1.ª persona del presente en valenciano para verbos en -ar: parle, treballe, estudie. Es la forma normativa valenciana (en otras zonas: parlo, parl).",["verbos","formas valencianas"],["parle parlo","primera persona"]),
("¿Cómo se forma el pasado perifrástico?","Presente de anar (vaig, vas, va, vam, vau, van) + infinitivo: vaig menjar = comí. Es el pasado más usado.",["pasado","verbos"],["vaig anar","pasado","perifrastico"]),
("¿«Vaig anar» es futuro?","No. «Vaig anar» = fui (pasado). Para «voy a ir» se usa el futuro «aniré» o el presente.",["pasado","calcos"],["voy a ir","vaig a anar"]),
("¿Se puede decir «vaig a fer»?","Para el futuro próximo es un calco del castellano; se recomienda «faré» o «ara faré». «Vaig a fer» solo es correcto con sentido de movimiento: vaig a fer la compra (voy a [un sitio a] hacer la compra).",["calcos","futuro"],["voy a hacer","vaig a"]),
("¿Cómo se forma el pretérito perfecto?","haver (he, has, ha, hem, heu, han) + participio: he menjat, hem arribat.",["pasado","verbos"],["he comido","perfecto"]),
("¿Cómo se forma el futuro?","Infinitivo + é, às, à, em, eu, an: parlaré, parlaràs, parlarà, parlarem, parlareu, parlaran.",["futuro","verbos"],["futuro"]),
("¿Cómo se forma el condicional?","Infinitivo + ia, ies, ia, íem, íeu, ien: parlaria. Irregulares: faria, tindria, vindria, podria, voldria.",["condicional","verbos"],["condicional"]),
("¿Cómo se forma el imperfecto?","-ar: parlava, parlaves… ; -er/-ir: temia, dormia. Irregulares: era (ser), feia (fer), deia (dir).",["verbos","pasado"],["imperfecto","hablaba"]),
("¿Cómo se forma el gerundio?","-ar → -ant (parlant), -er/-re → -ent (tement), -ir → -int (dormint). Estic menjant = estoy comiendo.",["verbos"],["gerundio","ando"]),
("¿Cómo se dice «tengo que»?","«Haver de» + infinitivo: he de treballar. «Tindre que» es coloquial; en registro cuidado se recomienda «haver de».",["calcos","verbos"],["tener que","tinc que"]),
("¿Cómo se dice «hay que»?","«Cal» + infinitivo: cal estudiar. O «s'ha de»: s'ha d'estudiar.",["verbos"],["hay que","cal"]),
("¿Cómo se dice «deberías»?","«Hauries de» + infinitivo: hauries de descansar.",["condicional"],["deberias","hauries"]),
("¿Cómo se dice «me gusta»?","«M'agrada» (singular) / «m'agraden» (plural): m'agrada l'arròs, m'agraden les taronges.",["verbos"],["gustar","m'agrada"]),
("¿Cómo se dice «me duele»?","Con «fer mal»: em fa mal el cap (me duele la cabeza), em fan mal els peus.",["salud","verbos"],["doler","fer mal"]),
("¿Cómo se dice «hace calor/frío»?","Con «fer»: fa calor, fa fred, fa sol, fa vent.",["tiempo"],["hace calor","fa fred"]),
("¿Cómo se dice «hay»?","«Hi ha» (para singular y plural): hi ha molta gent, hi ha tres cadires.",["verbos","pronombres"],["hay","hi ha"]),
("¿Cómo se dice «hace dos días»?","«Fa dos dies».",["tiempo"],["hace dias"]),
# --- pronombres débiles
("¿Qué son los pronombres débiles?","Pronombres átonos que acompañan al verbo: em, et, es, el, la, els, les, li, ho, en, hi… Equivalen a me, te, se, lo, la, le… pero «en» e «hi» no tienen equivalente directo.",["pronombres debiles"],["pronoms febles","pronombres atonos"]),
("¿Cómo se dice «lo veo»?","«El veig» (masculino), «la veig» (femenino), «ho veig» (neutro: eso).",["pronombres debiles"],["lo veo"]),
("¿Cuándo uso «ho»?","Para «lo» neutro (eso, una idea): no ho sé, ho entenc, fes-ho.",["pronombres debiles"],["ho","lo neutro"]),
("¿Qué significa «en» como pronombre?","Sustituye un complemento con «de» o una cantidad: Pa? En vull dos (quiero dos). Vinc de la platja → en vinc.",["pronombres debiles"],["pronombre en","en vull"]),
("¿Qué significa «hi»?","Sustituye un lugar o un complemento con a/en/amb: Hi vaig (voy allí). También en «hi ha».",["pronombres debiles"],["pronombre hi","hi vaig"]),
("¿Cómo se dice «se lo doy»?","«Li ho done» (eso a él/ella) o «l'hi done» (el objeto masculino a él/ella).",["pronombres debiles"],["se lo doy","li ho"]),
("¿Dónde se ponen los pronombres?","Delante del verbo conjugado (el veig) y detrás del infinitivo, gerundio e imperativo con guion: veure'l, dona-m'ho.",["pronombres debiles"],["posicion pronombres"]),
("¿Por qué se escribe «digues-m'ho» con guion?","En imperativo los pronombres van detrás, unidos con guion o apóstrofo: digues-m'ho, fes-ho, anem-nos-en.",["pronombres debiles","imperativo"],["dimelo","guion pronombre"]),
("¿Cómo se dice «me voy»?","«Me'n vaig» (con «en»). «Vámonos» = «anem-nos-en».",["pronombres debiles"],["me voy","men vaig"]),
("¿Cómo se dice «me acuerdo»?","«Me'n recorde» (de eso). «Me'n recorde de tu» = me acuerdo de ti.",["pronombres debiles"],["me acuerdo","recordar"]),
("¿Cómo se dice «le digo» y «les digo»?","«Li dic» (a él/ella) y «els dic» (a ellos).",["pronombres debiles"],["le digo les digo"]),
("¿«Me» o «em»?","Delante del verbo: «em» (em dic), «m'» ante vocal (m'agrada). Detrás: «-me» (dona-me). En la combinación delante también aparece «me»: me'l dones.",["pronombres debiles"],["em me"]),
("¿Por qué «l'he vista» concuerda?","Con el pronombre «la» delante del perfecto, el participio concuerda en femenino: la pel·lícula, l'he vista.",["pronombres debiles","participio"],["concordancia participio"]),
